char *parse_via(
                char *buffer, const char *const end, struct via_body *const vbody)
{
        char *tmp;
        char *param_start;
        unsigned char state;
        unsigned char saved_state;
        int c_nest;
        int err;
        struct via_body *vb;
        struct via_param *param;

        vb = vbody; /* keep orignal vbody value, needed to set the error member
                                * in case of multiple via bodies in the same header */
parse_again:
        vb->error = PARSE_ERROR;
        /* parse start of via ( SIP/2.0/UDP    )*/
        state = F_SIP;
        saved_state = F_SIP; /* fixes gcc 4.0 warning */
        param_start = 0;
        for(tmp = buffer; tmp < end; tmp++) {
                switch(*tmp) {
                        case ' ':
                        case '\t':
                                switch(state) {
                                        case L_VER: /* eat space */
                                        case L_PROTO:
                                        case F_SIP:
                                        case F_VER:
                                        case F_PROTO:
                                                break;
                                        case FIN_UDP:
                                                vb->transport.len = tmp - vb->transport.s;
                                                vb->proto = PROTO_UDP;
                                                state = F_HOST; /* start looking for host*/
                                                goto main_via;
                                        case FIN_TCP:
                                                /* finished proto parsing */
                                                vb->transport.len = tmp - vb->transport.s;
                                                vb->proto = PROTO_TCP;
                                                state = F_HOST; /* start looking for host*/
                                                goto main_via;
                                        case FIN_TLS:
                                                /* finished proto parsing */
                                                vb->transport.len = tmp - vb->transport.s;
                                                vb->proto = PROTO_TLS;
                                                state = F_HOST; /* start looking for host*/
                                                goto main_via;
                                        case FIN_SCTP:
                                                /* finished proto parsing */
                                                vb->transport.len = tmp - vb->transport.s;
                                                vb->proto = PROTO_SCTP;
                                                state = F_HOST; /* start looking for host*/
                                                goto main_via;
                                        case WS_WSS2:
                                                /* finished proto parsing */
                                                vb->transport.len = tmp - vb->transport.s;
                                                vb->proto = PROTO_WS;
                                                state = F_HOST; /* start looking for host*/
                                                goto main_via;
                                        case FIN_WSS:
                                                /* finished proto parsing */
                                                vb->transport.len = tmp - vb->transport.s;
                                                vb->proto = PROTO_WSS;
                                                state = F_HOST; /* start looking for host*/
                                                goto main_via;
                                        case OTHER_PROTO:
                                                /* finished proto parsing */
                                                vb->transport.len = tmp - vb->transport.s;
                                                vb->proto = PROTO_OTHER;
                                                state = F_HOST; /* start looking for host*/
                                                goto main_via;
                                        case UDP1:
                                        case UDP2:
                                        case TCP_TLS1:
                                        case TCP2:
                                        case TLS2:
                                        case SCTP1:
                                        case SCTP2:
                                        case SCTP3:
                                        case WS_WSS1:
